import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int modValue = 998244353;
        int totalN = sc.nextInt();
        int totalK = sc.nextInt();
        int[] freq = new int[10];
        for (int i = 0; i < totalK; i++) {
            freq[sc.nextInt()] = 1;
        }
        int[] base = {1};
        int halfN = totalN / 2;
        int[] current = base;
        while (halfN > 0) {
            if ((halfN & 1) == 1) {
                current = multiplyModulo(current, freq, modValue);
            }
            freq = multiplyModulo(freq, freq, modValue);
            halfN >>= 1;
        }
        int answer = 0;
        for (int val : current) {
            answer = (int)((answer + (long)val * val) % modValue);
        }
        System.out.println(answer);
        sc.close();
    }

    static int[] multiplyModulo(int[] a, int[] b, int mod) {
        int length = a.length + b.length - 1;
        int size = Integer.highestOneBit(length -1) << 1;
        double[] aRe = new double[size];
        double[] aIm = new double[size];
        for(int i=0; i<a.length; i++) {
            int x = a[i] % mod;
            aRe[i] = x & ((1<<15)-1);
            aIm[i] = x >> 15;
        }
        performFFT(aRe, aIm, false);
        double[] bRe = new double[size];
        double[] bIm = new double[size];
        for(int i=0; i<b.length; i++) {
            int x = b[i] % mod;
            bRe[i] = x & ((1<<15)-1);
            bIm[i] = x >> 15;
        }
        performFFT(bRe, bIm, false);
        double[] aRe2 = new double[size];
        double[] aIm2 = new double[size];
        double[] bRe2 = new double[size];
        double[] bIm2 = new double[size];
        for (int i=0; i<size; i++) {
            int j = (size - i) & (size - 1);
            double a1r = (aRe[i] + aRe[j]) / 2;
            double a1i = (aIm[i] - aIm[j]) / 2;
            double a2r = (aIm[i] + aIm[j]) / 2;
            double a2i = (aRe[j] - aRe[i]) / 2;
            double b1r = (bRe[i] + bRe[j]) / 2;
            double b1i = (bIm[i] - bIm[j]) / 2;
            double b2r = (bIm[i] + bIm[j]) / 2;
            double b2i = (bRe[j] - bRe[i]) / 2;
            aRe2[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            aIm2[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            bRe2[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            bIm2[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }
        performFFT(aRe2, aIm2, true);
        performFFT(bRe2, bIm2, true);
        int[] result = new int[length];
        for (int i=0; i<length; i++) {
            long aa = Math.round(aRe2[i]);
            long bb = Math.round(bRe2[i]);
            long cc = Math.round(aIm2[i]);
            result[i] = (int)((aa + (bb << 15) + (cc <<30)) % mod);
        }
        return result;
    }

    static void performFFT(double[] re, double[] im, boolean invert) {
        int n = re.length;
        int shiftVal = 32 - Integer.numberOfTrailingZeros(n);
        for (int i=1; i<n; i++) {
            int j = Integer.reverse(i << shiftVal);
            if (i<j) {
                double tempRe = re[i];
                re[i] = re[j];
                re[j] = tempRe;
                double tempIm = im[i];
                im[i] = im[j];
                im[j] = tempIm;
            }
        }
        for (int len=2; len<=n; len<<=1) {
            int half = len>>1;
            for (int i=0; i<n; i+=len) {
                int wIdx = cs.length / len;
