                    double wRe = invert ? csi[k] : cs[k];
                    double wIm = invert ? sni[k] : sn[k];
                    double uRe = re[i+j];
                    double uIm = im[i+j];
                    double vRe = re[i+j+half]*wRe - im[i+j+half]*wIm;
                    double vIm = re[i+j+half]*wIm + im[i+j+half]*wRe;
                    re[i+j] = uRe + vRe;
                    im[i+j] = uIm + vIm;
                    re[i+j+half] = uRe - vRe;
                    im[i+j+half] = uIm - vIm;
                }
            }
        }
        if (invert) {
            for (int i=0; i<n; i++) {
                re[i]/=n;
                im[i]/=n;
            }
        }
    }
